/** The `agent.*` operations. */
export class AgentOperations {
  /** The agent's ID. */
  readonly agent: string;
  /** The conversation the methods act on. `undefined` for the agent's own history. */
  readonly conversation: string | undefined;
  readonly #runner: Runner;

  /** @internal */
  constructor(runner: Runner, agent: string, conversation?: string | undefined) {
    this.#runner = runner;
    this.agent = agent;
    this.conversation = conversation;
  }

  /**
   * Read an agent's current status.
   */
  read(options: CallOptions = {}): Promise<Outputs["agent.read"]> {
    return this.#runner.call(
      "agent.read",
      { agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Define an agent.
   *
   * Creates the agent from this definition, or updates a running agent from its next turn. Each call replaces the whole definition. An unsupported key returns not_supported with the key's name.
   *
   * Acts on the agent, never a conversation.
   */
  define(input: AgentDefinition = {}, options: CallOptions = {}): Promise<Outputs["agent.define"]> {
    return this.#runner.call("agent.define", { ...input, agent: this.agent }, options);
  }

  /**
   * Delete an agent.
   *
   * Acts on the agent, never a conversation.
   */
  forget(options: CallOptions = {}): Promise<Outputs["agent.forget"]> {
    return this.#runner.call("agent.forget", { agent: this.agent }, options);
  }

  /**
   * Send a message to an agent.
   */
  ask(input: Ask, options: CallOptions = {}): Promise<Outputs["agent.ask"]> {
    return this.#runner.call(
      "agent.ask",
      { ...input, agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Approve or reject pending tool calls.
   *
   * All decisions are applied together and recorded under the caller. A rejection's reason is sent to the model instead of the tool's result. An approval's note is sent with the result.
   */
  decide(input: Decisions, options: CallOptions = {}): Promise<Outputs["agent.decide"]> {
    return this.#runner.call(
      "agent.decide",
      { ...input, agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Read the authorization URL for a pending call.
   */
  authorization(
    interrupt: string,
    options: CallOptions = {},
  ): Promise<Outputs["agent.authorization"]> {
    return this.#runner.call(
      "agent.authorization",
      { agent: this.agent, conversation: this.conversation, interrupt },
      options,
    );
  }

  /**
   * Cancel an agent's current turn.
   */
  cancel(options: CallOptions = {}): Promise<Outputs["agent.cancel"]> {
    return this.#runner.call(
      "agent.cancel",
      { agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Read an agent's events.
   */
  events(
    input: {
      /** The event types to return, for example wardrik.run.completed. List each type once. Defaults to all types. wardrik.events.dropped is always returned. */
      types?: string[] | undefined;
      /** Return events after this cursor. Use the next value from the previous page, an event ID from a stream, or the cursor from agent.read, agent.timeline or agent.runs. */
      after?: string | undefined;
      /** With order newest, return events before this cursor. Use the next value from the previous page. */
      before?: string | undefined;
      /** oldest returns the oldest events first, after the cursor; newest returns the newest first, before the cursor or from the end. Defaults to oldest. */
      order?: "oldest" | "newest" | undefined;
      /** The maximum number to return. Defaults to 100. */
      limit?: number | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["agent.events"]> {
    return this.#runner.call(
      "agent.events",
      { ...input, agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Like `events`, then follows each new event as it's written. Starts after `after`, or at
   * the end of the log. See `EventStream`.
   */
  streamEvents(
    input: {
      /** The event types to return, for example wardrik.run.completed. List each type once. Defaults to all types. wardrik.events.dropped is always returned. */
      types?: string[] | undefined;
      /** Return events after this cursor. Use the next value from the previous page, an event ID from a stream, or the cursor from agent.read, agent.timeline or agent.runs. */
      after?: string | undefined;
      /** With order newest, return events before this cursor. Use the next value from the previous page. */
      before?: string | undefined;
      /** oldest returns the oldest events first, after the cursor; newest returns the newest first, before the cursor or from the end. Defaults to oldest. */
      order?: "oldest" | "newest" | undefined;
    } = {},
    options: StreamOptions = {},
  ): EventStream {
    return this.#runner.stream(
      "agent.events",
      { ...input, agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Read an agent's conversation.
   */
  timeline(options: CallOptions = {}): Promise<Outputs["agent.timeline"]> {
    return this.#runner.call(
      "agent.timeline",
      { agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Read an agent's runs and their cost.
   */
  runs(options: CallOptions = {}): Promise<Outputs["agent.runs"]> {
    return this.#runner.call(
      "agent.runs",
      { agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Approve a pending tool call.
   *
   * Same as agent.decide with one approval. Recorded under the caller.
   */
  approve(
    interrupt: string,
    input: Approve = {},
    options: CallOptions = {},
  ): Promise<Outputs["agent.approve"]> {
    return this.#runner.call(
      "agent.approve",
      { ...input, agent: this.agent, conversation: this.conversation, interrupt },
      options,
    );
  }

  /**
   * Reject a pending tool call.
   *
   * Same as agent.decide with one rejection. Recorded under the caller.
   */
  deny(
    interrupt: string,
    input: Deny = {},
    options: CallOptions = {},
  ): Promise<Outputs["agent.deny"]> {
    return this.#runner.call(
      "agent.deny",
      { ...input, agent: this.agent, conversation: this.conversation, interrupt },
      options,
    );
  }

  /**
   * Read an agent's definition.
   *
   * Acts on the agent, never a conversation.
   */
  definition(options: CallOptions = {}): Promise<Outputs["agent.definition"]> {
    return this.#runner.call("agent.definition", { agent: this.agent }, options);
  }

  /**
   * Start an agent.
   *
   * Acts on the agent, never a conversation.
   */
  spawn(options: CallOptions = {}): Promise<Outputs["agent.spawn"]> {
    return this.#runner.call("agent.spawn", { agent: this.agent }, options);
  }

  /**
   * Stop an agent.
   */
  stop(options: CallOptions = {}): Promise<Outputs["agent.stop"]> {
    return this.#runner.call(
      "agent.stop",
      { agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Clear an agent's history.
   *
   * Deletes the agent's history. The agent, its definition and its other conversations are kept. Returns conflict while the agent is running a turn or waiting for an approval.
   */
  clear(options: CallOptions = {}): Promise<Outputs["agent.clear"]> {
    return this.#runner.call(
      "agent.clear",
      { agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * List an agent's running tool calls.
   *
   * Returns not_found while the agent is asleep.
   */
  calls(options: CallOptions = {}): Promise<Outputs["agent.calls"]> {
    return this.#runner.call(
      "agent.calls",
      { agent: this.agent, conversation: this.conversation },
      options,
    );
  }

  /**
   * Read an agent's resource use.
   *
   * Returns the memory, mailbox size and work of a running agent's processes. Returns not_found while the agent is asleep.
   *
   * Acts on the agent, never a conversation.
   */
  runtime(options: CallOptions = {}): Promise<Outputs["agent.runtime"]> {
    return this.#runner.call("agent.runtime", { agent: this.agent }, options);
  }

  /**
   * Read what an agent gets.
   *
   * Returns what the app gives the agent: who it works for, its policies, MCP servers and their tools, notify targets, channels and workspaces.
   *
   * Acts on the agent, never a conversation.
   */
  resolved(options: CallOptions = {}): Promise<Outputs["agent.resolved"]> {
    return this.#runner.call("agent.resolved", { agent: this.agent }, options);
  }

  /**
   * List an agent's files.
   *
   * Returns the files in the agent's workspace, newest first, at most 500. Files shared with it from other workspaces aren't listed.
   *
   * Acts on the agent, never a conversation.
   */
  files(
    input: {
      /** Return only the paths this glob matches: * within a folder, ? one character, ** across folders. Defaults to **. */
      glob?: string | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["agent.files"]> {
    return this.#runner.call("agent.files", { ...input, agent: this.agent }, options);
  }

  /**
   * Read an agent's file.
   *
   * Returns a file in the agent's workspace, with its content and version. Returns not_found if there's no file at the path.
   *
   * Acts on the agent, never a conversation.
   */
  file(
    input: {
      /** The file's path in the workspace, such as notes/today.md. */
      path: string;
    },
    options: CallOptions = {},
  ): Promise<Outputs["agent.file"]> {
    return this.#runner.call("agent.file", { ...input, agent: this.agent }, options);
  }

  /**
   * Write an agent's file.
   *
   * Writes a file in the agent's workspace. With version, writes only over that version and returns conflict if the file has changed. Without version, replaces any file at the path. The file carries no labels.
   *
   * Acts on the agent, never a conversation.
   */
  filePut(input: AgentFilePut, options: CallOptions = {}): Promise<Outputs["agent.file_put"]> {
    return this.#runner.call("agent.file_put", { ...input, agent: this.agent }, options);
  }

  /**
   * Delete an agent's file.
   *
   * Deletes a file in the agent's workspace. Returns not_found if there's no file at the path.
   *
   * Acts on the agent, never a conversation.
   */
  fileDelete(
    input: {
      /** The file's path in the workspace, such as notes/today.md. */
      path: string;
    },
    options: CallOptions = {},
  ): Promise<Outputs["agent.file_delete"]> {
    return this.#runner.call("agent.file_delete", { ...input, agent: this.agent }, options);
  }

  /**
   * Stop a tool call.
   */
  kill(call: string, options: CallOptions = {}): Promise<Outputs["agent.kill"]> {
    return this.#runner.call(
      "agent.kill",
      { agent: this.agent, conversation: this.conversation, call },
      options,
    );
  }

  /**
   * Create or update an agent's trigger.
   *
   * Creates or updates one trigger and saves it in the agent's definition. Returns not_found if the agent has no definition. If every and timezone don't change, the next run time is kept.
   *
   * Acts on the agent, never a conversation.
   */
  triggerSet(
    trigger: string,
    input: TriggerDefinition = {},
    options: CallOptions = {},
  ): Promise<Outputs["agent.trigger_set"]> {
    return this.#runner.call(
      "agent.trigger_set",
      { ...input, agent: this.agent, trigger },
      options,
    );
  }

  /**
   * Remove an agent's trigger.
   *
   * Acts on the agent, never a conversation.
   */
  triggerRemove(
    trigger: string,
    options: CallOptions = {},
  ): Promise<Outputs["agent.trigger_remove"]> {
    return this.#runner.call("agent.trigger_remove", { agent: this.agent, trigger }, options);
  }

  /**
   * Move an agent to another node.
   *
   * Restarts the agent on the given node, with its state. A turn in progress is stopped, and pending approvals are dropped. Send the request again after the move.
   */
  move(input: Node, options: CallOptions = {}): Promise<Outputs["agent.move"]> {
    return this.#runner.call(
      "agent.move",
      { ...input, agent: this.agent, conversation: this.conversation },
      options,
    );
  }
}

/** The `agents.*` operations. */
export class AgentsOperations {
  readonly #runner: Runner;

  /** @internal */
  constructor(runner: Runner) {
    this.#runner = runner;
  }

  /**
   * List agents.
   */
  list(
    input: {
      /** Agent IDs, each listed once. Each includes its conversations. Defaults to every agent you can access. */
      agents?: string[] | undefined;
      /** Return results after this cursor. Use the next value from the previous page. */
      after?: string | undefined;
      /** The maximum number to return. Defaults to all. */
      limit?: number | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["agents.list"]> {
    return this.#runner.call("agents.list", { ...input }, options);
  }

  /**
   * Delete agents.
   *
   * Removes each agent in the same way as agent.forget. The agent is stopped, and its conversations, definition and triggers are deleted.
   */
  forget(
    input: {
      /** Agent IDs, each listed once. Each includes its conversations. Defaults to every agent you can access. */
      agents?: string[] | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["agents.forget"]> {
    return this.#runner.call("agents.forget", { ...input }, options);
  }

  /**
   * Cancel the current turn of several agents.
   */
  cancel(
    input: {
      /** Agent IDs, each listed once. Each includes its conversations. Defaults to every agent you can access. */
      agents?: string[] | undefined;
    } = {},
    options: CallOptions = {},
  ): Promise<Outputs["agents.cancel"]> {
    return this.#runner.call("agents.cancel", { ...input }, options);
  }
}

